llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C64"],
      "claim": "Amphotericin B, the highest-transfer analogue (0.944), has negligible oral bioavailability after oral administration due to poor membrane permeability, low aqueous solubility, and gastric instability; its large polyhydroxylated macrocyclic structure with very high TPSA/HBA content is the closest mechanistic match to the query's extreme polarity and supports low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C52"],
      "claim": "Tacrolimus, a complex macrocyclic lactone with multiple oxygen functions, has absolute oral bioavailability of only 14±5% in healthy volunteers; this demonstrates that complex polycyclic natural products with high polar surface area can fall below the 20% threshold, supporting low F for the similarly complex and polar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Lefamulin, a diterpene with a tricyclic core, has absolute oral bioavailability of 25.8% in fasted healthy adults, just above the threshold; however, its higher lipophilicity and ionizable amine make it a less conservative model than the more polar, neutral query, so this evidence is only weakly contradictory.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "Zidovudine has ~60% oral bioavailability, but as a small nucleoside with transporter-mediated absorption and extensive first-pass metabolism, its high F is not mechanistically transferable to the large, rigid, highly polar polycyclic query; this high-F evidence is therefore weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query's very low logD, very high TPSA and HBA count, and rigid polycyclic lactone architecture align with the poor oral bioavailability of amphotericin B and the sub-20% F of tacrolimus; the closest diterpene analogue lefamulin is only borderline (25.8%) and is more lipophilic/ionizable. High-F small polar analogues are not mechanistically applicable.",
  "evidence_gaps": [
    "No direct experimental bioavailability or permeability data for the query or a close structural analogue with the same ring system.",
    "Uncertainty in extrapolating amphotericin B's negligible F to a smaller molecule without ionizable groups or sugar.",
    "Lack of information on active transport, efflux, or first-pass metabolism for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

